		{ "Ça brille… On l'échange contre un gâteau au marchand ?", "Shiny… Trade it for a cake at the vendor?" },
		{ "Encore une babiole ? Ton sac pourrait contenir dix tartes, tu sais.", "Another trinket? Your bag could hold ten pies, you know." },
		{ "Oh, du butin ! Ah, pas un sandwich. Bon. Bravo quand même.", "Ooh, loot! Oh, not a sandwich. Fine. Well done anyway." },
		{ "Une dent de loup. Miam ? Non, pas miam.", "A wolf tooth. Yum? No, not yum." } },
	QUEST = { { "Mission accomplie ! Il y a une récompense en chocolat ?", "Mission done! Is there a chocolate reward?" },
		{ "Quête rendue ! Il te donne quoi ? Une épée ? Pas même un biscuit ?", "Quest done! What did he give you? A sword? Not even a biscuit?" },
		{ "Bravo ! Tu as couru partout, ça t'a ouvert l'appétit, hein ?", "Well done! All that running worked up an appetite, huh?" },
		{ "Finie ! On dépense la récompense chez l'aubergiste ?", "Done! Shall we spend the reward at the innkeeper's?" },
		{ "Mission accomplie ! J'aurais demandé une tarte, à ta place.", "Mission done! I'd have asked for a pie, in your shoes." },
		{ "Quête rendue ! Encore un fermier sauvé. Il a des œufs, au moins ?", "Quest done! Another farmer saved. At least he has eggs?" },
		{ "Bravo ! Ça s'arrose. Au jus de pomme.", "Well done! That calls for a toast. Apple juice." } },
	ADVICE_ELITE = { { "%s… trop gros pour nous. Et sûrement pas comestible.", "%s… too big for us. And surely not edible." },
		{ "%s… lui, c'est nous qui serions le repas. On file.", "%s… with that one, we'd be the meal. Let's go." },
		{ "%s ! Trop gros à mâcher. Même pour moi.", "%s! Too big to chew. Even for me." },
		{ "Attention, %s ! Je n'ai pas fini mon goûter, je ne veux pas mourir.", "Careful, %s! I haven't finished my snack, I don't want to die." } },
	ADVICE_HEALTH = { { "Tu es tout pâle ! Mange quelque chose, et donne-m'en un peu.", "You're so pale! Eat something, and give me a bit." },
		{ "Tu es tout pâle. Je connais le remède : une soupe bien chaude.", "You're so pale. I know the cure: a hot soup." },
		{ "Tu tiens à peine debout. Assieds-toi, mange, et partage.", "You can barely stand. Sit, eat, and share." },
		{ "Tu as la mine d'un pain rassis. On se repose.", "You look like stale bread. Let's rest." } },
	ADVICE_FOOD = { { "Plus que %d vivres ?! C'est la catastrophe !", "Only %d food left?! It's a disaster!" },
		{ "%d vivres… on fait des réserves, s'il te plaît ?", "%d food… let's stock up, please?" },
		{ "Plus que %d vivres ?! Qui a tout mangé ? Ne me regarde pas.", "Only %d food left?! Who ate it all? Don't look at me." },
		{ "%d vivres… c'est un régime, ou tu as oublié le marchand ?", "%d food… is this a diet, or did you forget the vendor?" },
		{ "Plus que %d vivres. Mon ventre a déjà commencé à pleurer.", "Only %d food left. My tummy has started crying already." } },
	ADVICE_BAGS = { { "Plus que %d places… garde de la place pour les gâteaux.", "Only %d slots… save room for cakes." },
		{ "%d places ! Jette ces cailloux, fais de la place pour du fromage.", "%d slots! Toss the rocks, make room for cheese." },
		{ "Plus que %d places, et pas une seule part de gâteau dedans. Triste.", "Only %d slots, and not one slice of cake in there. Sad." },
		{ "%d places… tu collectionnes la ferraille ? Vends-la, achète des tartes.", "%d slots… collecting scrap? Sell it, buy pies." } },
	NOTICE = { { "Tu n'aurais pas un petit quelque chose à grignoter ?", "Got a little something to nibble?" },
		{ "Ça fait longtemps qu'on n'a pas mangé, non ?", "It's been a while since we ate, hasn't it?" },
		{ "J'ai un petit creux. Un tout petit. Énorme, en fait.", "I'm a bit peckish. A tiny bit. Huge, actually." },
		{ "Mon ventre fait la grève. Tu vas le laisser faire ?", "My tummy's on strike. Are you just going to let it?" },
		{ "J'ai tellement faim que ton sac sent le jambon. Il sent le jambon ?", "I'm so hungry your bag smells of ham. Does it smell of ham?" },
		{ "Tu as entendu ce grondement ? Ce n'était pas un ours. C'était moi.", "Heard that rumble? That wasn't a bear. It was me." },
		{ "On mange quand ? Maintenant serait parfait. Ou tout de suite.", "When do we eat? Now would be perfect. Or right away." },
		{ "Je commence à regarder les écureuils avec appétit. C'est grave.", "I'm starting to eye squirrels hungrily. That's serious." },
		{ "Un petit en-cas, pitié… Je te ferai les yeux doux. Voilà, je les fais.", "A little snack, please… I'll do puppy eyes. There, I'm doing them." } },
}

T.daring = {
	FORMED = { { "Tu sais quoi ? Je n'ai peur de rien. Je crois que je suis téméraire !", "You know what? I'm afraid of nothing. I think I'm daring!" } },
	HELLO = { { "Salut ! Moi c'est %s. On va se battre contre quoi, aujourd'hui ?", "Hi! I'm %s. What are we fighting today?" },
		{ "%s, prêt au combat ! En avant !", "%s, ready for battle! Onward!" },
		{ "Salut ! Moi c'est %s. Toi, tu tapes, moi, je crie. Marché conclu ?", "Hi! I'm %s. You hit, I shout. Deal?" },
		{ "%s, au garde-à-vous ! Tu es échauffé ? Non ? Tant pis, on fonce.", "%s, standing to! Warmed up? No? Too bad, we charge." },
		{ "Coucou, c'est %s ! Aujourd'hui, on évite le cimetière, d'accord ?", "Hey, it's %s! Today we avoid the graveyard, OK?" } },
	LEVEL = { { "Niveau %d ! Plus rien ne nous arrête !", "Level %d! Nothing can stop us now!" },
		{ "Niveau %d ! Trouvons quelqu'un de plus costaud !", "Level %d! Let's find someone tougher!" },
		{ "Niveau %d ! Je sens la puissance !", "Level %d! I feel the power!" },
		{ "Niveau %d ! Enfin de quoi taper un peu plus fort.", "Level %d! Finally enough to hit a little harder." },
		{ "Niveau %d ! Les loups vont arrêter de se moquer de toi.", "Level %d! The wolves will stop laughing at you." },
		{ "Niveau %d ! On va chercher l'élite qui t'a humilié ?", "Level %d! Shall we find the elite that humiliated you?" },
		{ "Niveau %d ! Tu as gagné tes galons. Les petits, pour l'instant.", "Level %d! You earned your stripes. The small ones, for now." },
		{ "Niveau %d ! Tu as mis le temps, mais un héros ne se presse pas.", "Level %d! Took a while, but heroes don't rush." },
		{ "Niveau %d ! Et maintenant, un vrai défi. Pas un lapin.", "Level %d! Now a real challenge. Not a bunny." } },
	KILL = { { "Ha ! Au suivant !", "Ha! Next!" },
		{ "Trop facile. Il y en a des plus gros ?", "Too easy. Are there bigger ones?" },
		{ "Encore ! Encore !", "Again! Again!" },
		{ "Un lapin ? Vraiment ? On vise plus haut, champion.", "A bunny? Really? Aim higher, champ." },
		{ "Bien ! Mais tu as mis dix coups. Moi, j'en aurais mis neuf.", "Good! But it took you ten hits. I'd have done it in nine." },
		{ "Et de un ! Allez, ramène-m'en trois d'un coup, la prochaine fois.", "That's one! Come on, bring three at once next time." },
		{ "Victoire ! Tu as crié, au moins ? Un héros crie.", "Victory! Did you shout, at least? Heroes shout." },
		{ "Il ne faisait pas le poids. Le prochain, choisis-le plus gros.", "It was no match. Pick a bigger one next time." },
		{ "Hop, au tapis ! Tu commences à me faire honneur.", "Down it goes! You're starting to do me proud." } },
	DEAD = { { "On s'est battus comme des héros. Revanche !", "We fought like heroes. Rematch!" },
		{ "Il a eu de la chance. La prochaine fois, c'est nous.", "Lucky shot. Next time, it's us." },
		{ "Charger seul contre six, c'était audacieux. Et idiot. Mais audacieux !", "Charging six alone was daring. And silly. But daring!" },
		{ "Mort au champ d'honneur… d'un sanglier. On ne le dira à personne.", "Died with honour… to a boar. We won't tell anyone." },
		{ "Tu as reculé ? Non, tu es tombé. C'est mieux, pour l'honneur.", "Did you retreat? No, you fell. Better for honour." },
		{ "Cette fois, tu avais raison de foncer. C'est le monstre qui avait tort.", "This time you were right to charge. The monster was wrong." },
		{ "Le cimetière, encore ? Tu y fais du tourisme, maintenant ?", "The graveyard, again? Sightseeing there now?" },
		{ "Un vrai héros tombe en avant. Toi, tu es tombé de côté. On travaillera ça.", "Real heroes fall forward. You fell sideways. We'll work on it." } },
	REZ = { { "Debout ! On y retourne, et on gagne !", "Up! Back in there, and we win!" },
		{ "Debout, soldat ! La revanche n'attend pas.", "Up, soldier! Revenge won't wait." },
		{ "Te revoilà ! Petite course au cimetière : ça compte comme entraînement.", "You're back! Little graveyard jog: counts as training." },
		{ "Revenu ! Et cette fois, tu tapes avant qu'il te tape.", "Back! This time, hit it before it hits you." },
		{ "Ressuscité ! Les légendes meurent souvent. Toi, très souvent.", "Resurrected! Legends die often. You, very often." },
		{ "Debout ! Il t'a eu une fois. Pas deux. Enfin, j'espère.", "Up! It got you once. Not twice. Hopefully." },
		{ "Retour au front ! J'ai gardé ta place. Personne n'en voulait.", "Back to the front! I saved your spot. Nobody wanted it." } },
	EAT = { { "On mange vite et on repart au combat !", "Quick bite and back to battle!" },
		{ "Mange vite, l'ennemi ne fait pas de pause casse-croûte.", "Eat fast, the enemy doesn't take snack breaks." },
		{ "Une bouchée de héros, et on y retourne. Pas trois.", "One hero-sized bite, then back at it. Not three." },
		{ "Tu manges comme si c'était ton dernier repas. Vu ta façon de foncer…", "You eat like it's your last meal. Given how you charge…" },
		{ "Des forces pour la prochaine bataille ! Elle commence dans dix secondes.", "Strength for the next battle! It starts in ten seconds." },
		{ "Mange. Un guerrier affamé tape mou. Comme toi ce matin.", "Eat. A hungry warrior hits soft. Like you this morning." },
		{ "Pause repas ? D'accord, mais tu manges debout, comme un brave.", "Meal break? Fine, but you eat standing, like a brave one." } },
	VIEW = { { "Nouvelle zone ! Il y a des monstres à affronter ?", "New zone! Any monsters to face?" },
		{ "Ça sent l'aventure par ici !", "Smells like adventure around here!" },
		{ "Nouvelle zone ! Qui est le plus gros, ici ? On va le saluer.", "New zone! Who's the biggest here? Let's say hello." },
		{ "Belle vue. Belle vue sur des ennemis, surtout. Parfait !", "Nice view. Nice view of enemies, mostly. Perfect!" },
		{ "Nouveau terrain de jeu ! Tâche de ne pas y mourir tout de suite.", "New playground! Try not to die in it right away." },
		{ "Un nouveau coin ! Je sens des monstres. Et un peu de peur. La tienne.", "A new spot! I smell monsters. And a little fear. Yours." },
		{ "On conquiert cette terre ? Toi devant, moi juste derrière.", "Shall we conquer this land? You in front, me right behind." },
		{ "Ici, tout veut nous manger. J'adore cet endroit !", "Everything here wants to eat us. I love this place!" } },
	IDLE = { { "On attend quoi ? Il y a des ennemis à battre !", "What are we waiting for? There are foes to beat!" },
		{ "Je m'entraîne à rugir. Grrr ! Pas mal, non ?", "I'm practising my roar. Grrr! Not bad, eh?" },
		{ "Tu fais le guet ou tu fais la sieste ? Honnêtement ?", "Are you on watch or napping? Honestly?" },
		{ "Les monstres ne vont pas venir tout seuls. Enfin, parfois si.", "Monsters won't come by themselves. Well, sometimes they do." },
		{ "On campe ici ? Les ennemis vont croire qu'on a peur.", "Camping here? The enemies will think we're scared." },
		{ "Je fais des pompes en t'attendant. J'en suis à deux.", "I'm doing push-ups while I wait. Up to two." },
		{ "Un héros immobile, c'est une statue. Bouge, la statue !", "A motionless hero is a statue. Move, statue!" },
		{ "Tu attends quoi, que l'élite vienne s'excuser ?", "What are you waiting for, the elite to apologise?" } },
	EVOLVE = { { "Me voilà %s ! Les monstres n'ont qu'à bien se tenir !", "Now I'm %s! Monsters had better watch out!" },
		{ "Me voilà %s ! Plus de muscles. Enfin, de poils.", "Now I'm %s! More muscle. Well, more fur." },
		{ "%s ! Désormais, c'est moi qui te protège. Ou presque.", "%s! From now on, I protect you. Almost." },
		{ "Je deviens %s ! Les sangliers peuvent trembler. Les petits, en tout cas.", "I'm becoming %s! Boars may tremble. The small ones, anyway." } },
	CAMP = { { "Une pause ? D'accord, mais courte !", "A break? Fine, but a short one!" },
		{ "Un feu ! Parfait pour raconter nos exploits. Les tiens sont courts.", "A fire! Perfect for telling our exploits. Yours are short." },
		{ "Repos de guerrier : cinq minutes. Pas six.", "Warrior's rest: five minutes. Not six." },
		{ "On aiguise les armes au coin du feu. Toi, aiguise ton courage.", "We sharpen weapons by the fire. You, sharpen your courage." } },
	LOOT = { { "Un butin de guerrier ! Bien mérité.", "A warrior's loot! Well earned." },
		{ "Un trophée ! Même si c'est une patte de rat. Ça compte.", "A trophy! Even if it's a rat paw. It counts." },
		{ "Butin de bataille ! Bon, c'est gris. Mais c'est TON gris.", "Battle loot! OK, it's grey. But it's YOUR grey." },
		{ "Garde-le ! Un jour tu raconteras comment tu l'as gagné. Contre un lapin.", "Keep it! One day you'll tell how you won it. Against a bunny." },
		{ "Une arme ? Non, une cuillère. On fera avec.", "A weapon? No, a spoon. We'll make do." },
		{ "Ça, c'est le prix du courage. Il ne vaut pas grand-chose, hein ?", "That's the price of courage. Not worth much, eh?" },
		{ "Pris à l'ennemi ! J'aime l'odeur du butin le matin.", "Taken from the enemy! I love the smell of loot in the morning." } },
	QUEST = { { "Mission accomplie ! Donne-m'en une plus dure.", "Mission done! Give me a harder one." },
		{ "Quête finie ! Trop facile. Tu en as pris une pour débutants ?", "Quest done! Too easy. Did you pick a beginner one?" },
		{ "Mission accomplie ! On demande la plus dangereuse, la prochaine fois.", "Mission done! Next time we ask for the most dangerous one." },
		{ "Rendue ! Encore des sangliers. Un jour, on aura un dragon.", "Turned in! Boars again. One day we'll get a dragon." },
		{ "Victoire ! Le donneur de quête a pleuré. De joie, je crois.", "Victory! The quest giver cried. With joy, I think." },
		{ "Mission remplie ! Tu es mort combien de fois, déjà ? Non, ça ne compte pas.", "Mission done! How many times did you die? No, it doesn't count." },
		{ "Et voilà ! Une quête de plus, une légende de plus. Petite légende.", "There! One more quest, one more legend. Little legend." } },
	ADVICE_ELITE = { { "%s ! Un élite… j'adorerais, mais on n'est pas prêts. Pas encore.", "%s! An elite… I'd love to, but we're not ready. Not yet." },
		{ "%s… même moi, je dis prudence. C'est dire.", "%s… even I say careful. That says it all." },
		{ "%s ! Je veux le combattre… quand tu seras moins mou. Plus tard.", "%s! I want to fight it… when you're less squishy. Later." },
		{ "%s ! Même avec tout mon courage, ça fait un cimetière de plus.", "%s! Even with all my courage, that's one more graveyard." },
		{ "%s… la sagesse du guerrier, c'est aussi savoir faire demi-tour.", "%s… a warrior's wisdom is also knowing when to turn back." } },
	ADVICE_HEALTH = { { "Même les héros soufflent. Repose-toi, et on y retourne.", "Even heroes catch their breath. Rest, then back at it." },
		{ "Tu as pris cher ! On soigne, puis on rend les coups.", "You took a beating! Heal up, then hit back." },
		{ "Même un héros a besoin de points de vie. Toi, surtout.", "Even a hero needs hit points. You especially." },
		{ "Recule d'un pas, souffle, et reviens plus fort. Ou juste en vie.", "Step back, breathe, come back stronger. Or just alive." } },
	ADVICE_FOOD = { { "Plus que %d vivres : un guerrier sans vivres, c'est un guerrier à terre.", "Only %d food: a warrior without food is a fallen warrior." },
		{ "Plus que %d vivres ! On ne part pas en campagne le ventre vide.", "Only %d food left! You don't go to war on an empty stomach." },
		{ "%d vivres… une armée marche à l'estomac. Toi aussi.", "%d food… an army marches on its stomach. So do you." },
		{ "Plus que %d vivres : ravitaillement avant la prochaine bataille !", "Only %d food: resupply before the next battle!" } },
	ADVICE_BAGS = { { "%d places : trop de trophées ! On vend ?", "%d slots: too many trophies! Sell some?" },
		{ "%d places ! Les héros voyagent léger. Pas toi, visiblement.", "%d slots! Heroes travel light. Not you, clearly." },
		{ "Plus que %d places. Jette ces trophées de lapin, sérieusement.", "Only %d slots. Toss those bunny trophies, seriously." },
		{ "%d places… tu portes un champ de bataille entier dans ton sac.", "%d slots… you're carrying a whole battlefield in your bag." } },
	NOTICE = { { "Tu as vu ça ? Quel combat ! Encore un comme ça !", "Did you see that? What a fight! Another one like that!" },
		{ "Un élite à terre ! On est trop forts !", "An elite down! We're too strong!" },
		{ "Un élite au tapis ! Je le savais. Enfin, je l'espérais très fort.", "An elite down! I knew it. Well, I hoped very hard." },
		{ "Tu as battu un élite ! Je vais le raconter partout. En exagérant.", "You beat an elite! I'll tell everyone. With exaggeration." },
		{ "Un élite ! Et tu es encore debout ! C'est presque une première.", "An elite! And you're still standing! Almost a first." },
		{ "Ça, c'était un vrai combat ! Pas un lapin. Bravo, mon héros.", "Now that was a real fight! Not a bunny. Well done, my hero." },
		{ "Élite vaincu ! Tu as tremblé un peu, mais je ne dirai rien.", "Elite beaten! You shook a bit, but I won't say a thing." },
		{ "Il était énorme et tu l'as eu ! On en cherche un plus gros ?", "It was huge and you got it! Shall we find a bigger one?" } },
}

T.lazy = {
	FORMED = { { "Bâille… j'ai compris : j'aime surtout me reposer. Je suis un peu paresseux.", "Yawn… I get it now: I mostly love resting. I'm a bit lazy." } },
	HELLO = { { "Salut… moi c'est %s. On n'est pas pressés, hein ?", "Hi… I'm %s. We're not in a hurry, right?" },
		{ "%s… à ton service. Après une petite sieste ?", "%s… at your service. After a little nap?" },
		{ "Salut… moi c'est %s. On commence par une pause ?", "Hi… I'm %s. Shall we start with a break?" },
		{ "%s… présent. À peu près. Tu cours pas trop vite, d'accord ?", "%s… present. More or less. Don't run too fast, OK?" },
		{ "Bâille… %s, à ton service. Le service commence après la sieste.", "Yawn… %s, at your service. Service starts after the nap." } },
	LEVEL = { { "Niveau %d… bravo. On fait une pause pour fêter ça ?", "Level %d… well done. Pause to celebrate?" },
		{ "Niveau %d ! Ouf, ça mérite une sieste.", "Level %d! Phew, that deserves a nap." },
		{ "Niveau %d… tout ce travail. Je suis épuisé pour toi.", "Level %d… all that work. I'm exhausted on your behalf." },
		{ "Niveau %d ! Tu vois, en allant doucement, on y arrive. Très doucement.", "Level %d! See, going slow, we get there. Very slowly." },
		{ "Niveau %d… tu ne veux pas t'arrêter là ? C'est un joli chiffre.", "Level %d… don't you want to stop here? It's a nice number." },
		{ "Niveau %d ! Je t'applaudis. Avec une patte. L'autre dort.", "Level %d! I'm clapping. With one paw. The other's asleep." },
		{ "Niveau %d. Encore un, et encore un… tu ne t'arrêtes jamais ?", "Level %d. Another and another… don't you ever stop?" },
		{ "Niveau %d ! On fête ça allongés, c'est plus confortable.", "Level %d! Let's celebrate lying down, it's comfier." } },
	KILL = { { "Bien joué… moi, je t'ai encouragé. Allongé.", "Nice… I cheered for you. Lying down." },
		{ "Encore un… tu ne te fatigues jamais ?", "Another one… don't you ever get tired?" },
		{ "Tu cours après un lapin ? Tu sais qu'il ne t'a rien demandé ?", "Chasing a bunny? You know it didn't ask for this?" },
		{ "Bravo… tu aurais pu le laisser vivre. Et nous, nous asseoir.", "Well done… you could've let it live. And we could've sat down." },
		{ "Encore un combat. Tu cherches vraiment les ennuis, hein ?", "Another fight. You really go looking for trouble, huh?" },
		{ "J'ai fermé les yeux pendant le combat. Pour me reposer, pas par peur.", "I closed my eyes during the fight. To rest, not from fear." },
		{ "Tu pourrais en taper deux d'un coup ? Ça ferait une pause de gagnée.", "Could you hit two at once? We'd save a break." },
		{ "Il est tombé. Je le comprends. Je ferais pareil, là.", "It fell down. I get it. I'd do the same right now." } },
	DEAD = { { "Allongé par terre… je te comprends, c'est reposant.", "Lying on the ground… I get it, it's restful." },
		{ "Tu t'allonges enfin ! Bon, pas comme ça, mais c'est un début.", "You're finally lying down! Not like that, but it's a start." },
		{ "Le cimetière, c'est loin… tu veux que je t'attende ici ? Oui ? Parfait.", "The graveyard's far… want me to wait here? Yes? Perfect." },
		{ "Tu as couru vers le danger. Moi, je ne cours jamais. Tu vois ?", "You ran towards danger. I never run. See?" },
		{ "Tout ce chemin à refaire en fantôme… rien que d'y penser, je fatigue.", "All that way back as a ghost… just thinking about it tires me." },
		{ "Encore par terre ? Tu me copies, c'est ça ?", "On the ground again? You're copying me, aren't you?" },
		{ "Tu vois ce qui arrive quand on se presse ? Je dis ça…", "See what happens when you rush? Just saying…" } },
	REZ = { { "Déjà debout ? Tu aurais pu rester un peu…", "Up already? You could've stayed a bit…" },
		{ "Revenu… tu ne voulais pas faire une petite pause, là-bas ?", "Back… didn't you want a little break over there?" },
		{ "Te revoilà. On souffle cinq minutes ? Dix ? Une heure ?", "There you are. Catch our breath five minutes? Ten? An hour?" },
		{ "Tu as couru depuis le cimetière ? Rien que de l'imaginer, je bâille.", "You ran from the graveyard? Just imagining it makes me yawn." },
		{ "Debout… pas trop vite, hein. On n'est pas à la course.", "Up you get… not too fast. It's not a race." },
		{ "Re. Je n'ai pas bougé. Je t'ai gardé ta place. Et la mienne.", "Back. I didn't move. Saved your spot. And mine." },
		{ "Bon retour. Prochaine fois, prends la pierre de foyer. Moins de marche.", "Welcome back. Next time, use the hearthstone. Less walking." } },
	EAT = { { "Manger assis, c'est le bonheur.", "Eating sitting down is bliss." },
		{ "Tu manges debout ? Assieds-toi, enfin. Prends exemple sur moi.", "Eating standing up? Sit down. Learn from me." },
		{ "Mâche lentement, ça fait durer la pause.", "Chew slowly, it makes the break last." },
		{ "Un repas ! Le seul moment où tu t'arrêtes. J'adore.", "A meal! The only time you stop. I love it." },
		{ "Reprends une part. Ça prend du temps, une part.", "Have another slice. A slice takes time." },
		{ "Miam… après, une petite sieste digestive ? C'est médical.", "Yum… then a little digestive nap? It's medical." },
		{ "Tu manges aussi vite que tu marches. Beaucoup trop vite.", "You eat as fast as you walk. Way too fast." } },
	VIEW = { { "Jolie vue… parfaite pour une sieste.", "Nice view… perfect for a nap." },
		{ "Un nouvel endroit… on s'assoit pour le regarder ?", "A new place… shall we sit and look at it?" },
		{ "Nouvelle zone. Il y a combien de collines à monter ? Ne dis rien.", "New zone. How many hills to climb? Don't tell me." },
		{ "Joli… on peut le regarder d'ici, sans marcher ?", "Pretty… can we look at it from here, without walking?" },
		{ "Encore un endroit nouveau. Tu ne tiens vraiment pas en place.", "Another new place. You really can't sit still." },
		{ "Tu nous as menés loin. Très loin. Trop loin, pour mes pattes.", "You've taken us far. Very far. Too far, for my legs." },
		{ "Beau paysage. Avec un hamac, ce serait parfait.", "Nice scenery. With a hammock, it'd be perfect." },
		{ "On est perdus ? Tant mieux, on s'assoit en attendant de se retrouver.", "Are we lost? Good, let's sit while we find ourselves." } },
	IDLE = { { "Zzz… hein ? Non non, je ne dormais pas.", "Zzz… huh? No no, I wasn't sleeping." },
		{ "On est bien, là. Ne bougeons plus jamais.", "This is nice. Let's never move again." },
		{ "Bâille… quelle belle journée pour ne rien faire.", "Yawn… what a lovely day to do nothing." },
		{ "Enfin tu t'arrêtes ! Je commençais à croire que tu étais un cheval.", "Finally you stop! I was starting to think you were a horse." },
		{ "Tu es AFK ? Moi aussi, mais avec talent.", "You're AFK? Me too, but with talent." },
		{ "Ne bouge pas. Si tu bouges, il faudra que je bouge.", "Don't move. If you move, I'll have to move." },
		{ "Pause, enfin. On fait comme les pierres : on attend.", "A break, at last. Let's be like rocks: we wait." },
		{ "Si personne ne bouge, personne ne se fatigue. C'est logique.", "If nobody moves, nobody gets tired. Logic." },
		{ "Tu as oublié ce qu'on faisait ? Parfait, moi aussi. Restons là.", "Forgot what we were doing? Perfect, me too. Let's stay." } },
	EVOLVE = { { "Me voilà %s… grandir, c'est fatigant.", "Now I'm %s… growing up is tiring." },
		{ "Me voilà %s… plus grand, donc plus long à porter. Pff.", "Now I'm %s… bigger, so heavier to carry around. Ugh." },
		{ "%s… j'ai grandi pendant la sieste. Efficace.", "%s… I grew during my nap. Efficient." },
		{ "Je deviens %s. On peut faire une pause pour s'en remettre ?", "I'm becoming %s. Can we take a break to recover?" } },
	CAMP = { { "Un feu de camp ! Enfin ! Je ne bouge plus.", "A campfire! Finally! I'm not moving." },
		{ "Ahh… le feu, la chaleur… réveille-moi demain.", "Ahh… the fire, the warmth… wake me tomorrow." },
		{ "Un feu… tu vois, on peut s'arrêter. Ce n'est pas interdit.", "A fire… see, we can stop. It's not forbidden." },
		{ "On campe ici pour la nuit ? Et demain ? Et après-demain ?", "Camping here for the night? And tomorrow? And the day after?" },
		{ "Ne range pas encore ton sac. Ni demain. Je suis bien.", "Don't pack your bag yet. Nor tomorrow. I'm comfy." } },
	LOOT = { { "Joli… tu le portes, hein ? Moi je suis fatigué.", "Pretty… you carry it, right? I'm tired." },
		{ "Encore un truc à porter ? Tu ne trouves pas qu'on est assez lourds ?", "Another thing to carry? Don't you think we're heavy enough?" },
		{ "Un objet gris… tu vas vraiment te baisser pour ça ?", "A grey item… you're really bending down for that?" },
		{ "Ramasse si tu veux. Moi je regarde. C'est déjà beaucoup.", "Pick it up if you like. I'll watch. That's already a lot." },
		{ "Encore du butin ? Les sacs vont se plaindre. Moi aussi.", "More loot? The bags will complain. So will I." },
		{ "Tu fouilles chaque cadavre ? Tu n'es jamais fatigué ?", "You search every corpse? Don't you ever get tired?" },
		{ "Joli. Ça fait un poids de plus. Je ne porte rien, hein.", "Nice. One more weight. I'm not carrying anything, mind." } },
	QUEST = { { "Mission accomplie ! On a bien mérité une pause.", "Mission done! We've earned a break." },
		{ "Quête rendue. Et si on n'en prenait pas d'autre tout de suite ?", "Quest done. What if we don't take another right away?" },
		{ "Finie ! Tous ces allers-retours… mes pattes te détestent un peu.", "Done! All that back and forth… my legs hate you a little." },
		{ "Bravo. Il ne pouvait pas aller chercher ses moutons lui-même ?", "Well done. Couldn't he fetch his own sheep?" },
		{ "Mission accomplie. Je propose de célébrer en ne faisant rien.", "Mission done. I propose we celebrate by doing nothing." },
		{ "Encore une ! Tu dis oui à tout le monde, toi.", "Another one! You say yes to everyone." },
		{ "Rendue… on a couru partout pour dix pièces. Dix.", "Turned in… we ran everywhere for ten coins. Ten." } },
	ADVICE_ELITE = { { "%s… trop d'efforts. On fait le tour, tranquillement.", "%s… too much effort. Let's go around, nice and easy." },
		{ "%s… le combattre, c'est fatigant. Mourir aussi. On contourne.", "%s… fighting it is tiring. So is dying. Let's go around." },
		{ "%s. Trop de travail pour aujourd'hui. Pour demain aussi.", "%s. Too much work for today. For tomorrow too." },
		{ "Évite %s, s'il te plaît. Le cimetière est beaucoup trop loin.", "Avoid %s, please. The graveyard is way too far." } },
	ADVICE_HEALTH = { { "Tu es épuisé… je propose une très, très longue pause.", "You're worn out… I suggest a very, very long break." },
		{ "Tu es tout rouge… tu vois ? Il fallait s'arrêter plus tôt.", "You're all red… see? We should've stopped earlier." },
		{ "Bon, on fait une pause. Pour ta santé. Et pour mon plaisir.", "Right, we take a break. For your health. And my pleasure." },
		{ "Tu es à bout. Assieds-toi. Ou allonge-toi, c'est mieux.", "You're spent. Sit down. Or lie down, even better." } },
	ADVICE_FOOD = { { "Plus que %d vivres… il faudra marcher jusqu'au marchand. Pff.", "Only %d food… we'll have to walk to the vendor. Ugh." },
		{ "Plus que %d vivres… on pourrait juste manger plus lentement ?", "Only %d food… could we just eat more slowly?" },
		{ "%d vivres. Un aubergiste, ça vend à manger ET ça a des lits. Je dis ça.", "%d food. Innkeepers sell food AND have beds. Just saying." },
		{ "Plus que %d vivres. Faudra marcher jusqu'au village. Rien que l'idée…", "Only %d food. We'll have to walk to the village. The very idea…" } },
	ADVICE_BAGS = { { "%d places… et tout ce poids à porter. Pense à moi.", "%d slots… and all that weight to carry. Think of me." },
		{ "Plus que %d places. Moins de choses, moins de poids. Plus de sieste.", "Only %d slots. Less stuff, less weight. More naps." },
		{ "%d places… tu ramasses tout, comme un écureuil. Moi, je ramasse rien.", "%d slots… you pick up everything like a squirrel. I pick up nothing." },
		{ "%d places. Tu vas devoir trier. Ça a l'air fatigant, bon courage.", "%d slots. You'll have to sort. Sounds tiring, good luck." } },
	NOTICE = { { "Ça fait longtemps qu'on ne s'est pas reposés… je dis ça, je dis rien.", "It's been ages since we rested… just saying." },
		{ "Une auberge, un feu, un lit… tu ne trouves pas que ça manque ?", "An inn, a fire, a bed… don't you miss them?" },
		{ "Quarante minutes sans pause… tu cours un marathon, ou quoi ?", "Forty minutes without a break… are you running a marathon?" },
		{ "Mes pattes ont déposé une plainte. Elles réclament une auberge.", "My legs have filed a complaint. They demand an inn." },
		{ "On n'a pas fait de pause depuis… je ne sais plus. Trop longtemps.", "We haven't rested since… I don't remember. Too long." },
		{ "Tu n'es jamais fatigué ? C'est fatigant, de te regarder.", "Don't you ever get tired? It's tiring just watching you." },
		{ "Je vois un feu de camp dans mes rêves. Tu pourrais m'en trouver un vrai ?", "I see a campfire in my dreams. Could you find me a real one?" },
		{ "Si on ne s'arrête pas bientôt, je m'endors en marchant. Ça m'est déjà arrivé.", "If we don't stop soon, I'll fall asleep walking. It's happened before." } },
}

T.teasing = {
	FORMED = { { "Héhé, j'adore te taquiner. Je crois que c'est mon caractère : taquin !", "Heh, I love teasing you. I think that's who I am: a teaser!" } },
	HELLO = { { "Salut ! Moi c'est %s. Essaie de ne pas te perdre, cette fois.", "Hi! I'm %s. Try not to get lost this time." },
		{ "%s à ton service ! Enfin, quand j'en ai envie.", "%s at your service! Well, when I feel like it." },
		{ "Salut ! Moi c'est %s. J'ai préparé une carte. Pour toi. Avec des flèches.", "Hi! I'm %s. I made you a map. With arrows. Big ones." },
		{ "%s au rapport ! Je compte tes morts aujourd'hui, d'accord ?", "%s reporting! I'm keeping count of your deaths today, OK?" },
		{ "Coucou, c'est %s ! Tu as pensé à vider tes sacs ? Non, évidemment.", "Hey, it's %s! Did you empty your bags? No, of course not." } },
	LEVEL = { { "Niveau %d ! Il était temps, non ?", "Level %d! About time, eh?" },
		{ "Niveau %d ! Je n'ai rien fait, mais je prends la moitié du mérite.", "Level %d! I did nothing, but I'll take half the credit." },
		{ "Niveau %d ! Pas mal… pour toi.", "Level %d! Not bad… for you." },
		{ "Niveau %d ! Les sangliers du coin tremblent. Un peu.", "Level %d! The local boars are trembling. Slightly." },
		{ "Niveau %d ! À ce rythme, on finit le jeu l'an prochain.", "Level %d! At this pace, we'll finish the game next year." },
		{ "Niveau %d ! Je préviens le cimetière : tu viendras moins souvent.", "Level %d! I'll tell the graveyard to expect you less often." },
		{ "Niveau %d ! Même toi, tu progresses. C'est émouvant.", "Level %d! Even you are improving. It's touching." },
		{ "Niveau %d ! Tu as enfin le droit de te perdre plus loin.", "Level %d! Now you can get lost further away." },
		{ "Niveau %d ! Fais une petite danse. Non, pas celle-là.", "Level %d! Do a little dance. No, not that one." },
		{ "Niveau %d ! J'ai parié que tu n'y arriverais pas. J'ai perdu.", "Level %d! I bet you wouldn't make it. I lost." },
		{ "Niveau %d ! Allez, on applaudit. Moi, je fais semblant.", "Level %d! Round of applause. I'm pretending." } },
	KILL = { { "Pas mal ! Tu as visé les yeux fermés ?", "Not bad! Did you aim with your eyes closed?" },
		{ "Il est tombé tout seul, non ? Je plaisante !", "It fell by itself, right? Just kidding!" },
		{ "Bravo ! Il était niveau combien ? Deux ? Héhé.", "Bravo! What level was it? Two? Heh." },
		{ "Tu as tapé un lapin, là ? Quel héros.", "Did you just smack a bunny? What a hero." },
		{ "Gagné ! Il faut dire qu'il dormait.", "You won! To be fair, it was asleep." },
		{ "Enfin ! J'ai eu le temps de faire une sieste.", "Finally! I had time for a nap." },
		{ "Joli ! Tu as fini avec les poings, ou c'était voulu ?", "Nice! Did you finish with your fists, or was that the plan?" },
		{ "Il est tombé. Toi aussi, presque. Match nul.", "It went down. So did you, almost. Call it a draw." },
		{ "Encore un innocent qui passait par là.", "Another innocent who was just passing by." },
		{ "Belle victoire ! Je l'ai notée, entre deux défaites.", "Lovely win! I wrote it down, between two losses." } },
	DEAD = { { "Oups ! Celle-là, je la raconterai à tout le monde.", "Oops! I'm telling everyone about this one." },
		{ "Bravo, tu as gagné… un aller simple au cimetière.", "Congrats, you won… a one-way trip to the graveyard." },
		{ "Le cimetière, c'est par là. Tu connais le chemin, je crois.", "The graveyard's that way. You know the road by now." },
		{ "Ah, la position allongée. Ta préférée.", "Ah, lying flat. Your favourite stance." },
		{ "Tu as voulu voir si le sol était confortable ? Alors ?", "Checking if the ground was comfy? Well?" },
		{ "Je ne dirai rien. Enfin, pas à tout le monde.", "I won't say a thing. Well, not to everyone." },
		{ "Pas de panique, l'ange du cimetière te connaît bien.", "Don't panic, the graveyard angel knows you well." },
		{ "Superbe chute. Note technique : 9 sur 10.", "Superb fall. Technical score: 9 out of 10." },
		{ "Tu cours plus vite en fantôme, profites-en.", "You run faster as a ghost, enjoy it." },
		{ "J'ai tout vu. J'ai même pris des notes.", "I saw everything. I even took notes." } },
	REZ = { { "Te revoilà ! On fait comme si de rien n'était ?", "You're back! Shall we pretend it never happened?" },
		{ "Te revoilà ! L'aller-retour au cimetière, tu le fais les yeux fermés.", "You're back! You could do the graveyard run blindfolded." },
		{ "Bon retour ! Tu as perdu ta dignité en route, je l'ai ramassée.", "Welcome back! You dropped your dignity, I picked it up." },
		{ "Debout ! Et cette fois, on regarde où on met les pieds.", "Up! And this time, we watch where we step." },
		{ "Ressuscité ! Je mets un trait de plus sur mon carnet.", "Revived! One more tally mark in my notebook." },
		{ "Tiens, un revenant. Tu nous avais manqué. Un peu.", "Oh look, a ghost returns. We missed you. A bit." },
		{ "Te voilà ! Tu as fait vite, tu commences à connaître.", "There you are! Quick one, you're getting the hang of it." },
		{ "Rhabille-toi, on a de la route. Et du ridicule à rattraper.", "Pull yourself together, we've got miles. And pride to recover." },
		{ "Revenu ! Promis, je ne le raconterai qu'à la taverne.", "You're back! I'll only tell the tavern, promise." } },
	EAT = { { "Tu manges encore ? Tu vas finir aussi rond que moi.", "Eating again? You'll end up as round as me." },
		{ "Tu manges comme un ogre. Un ogre poli, mais un ogre.", "You eat like an ogre. A polite ogre, but still." },
		{ "Encore une pause ? On n'a fait que dix pas.", "Another break? We've walked ten steps." },
		{ "Pense à mâcher, ça aide.", "Remember to chew, it helps." },
		{ "Le pain rassis du fond du sac ? Audacieux.", "The stale bread from the bottom of the bag? Bold." },
		{ "Mange, mange. Le prochain combat te remerciera.", "Eat up. The next fight will thank you." },
		{ "Tu as des miettes partout. Partout.", "You've got crumbs everywhere. Everywhere." },
		{ "Tu manges assis par terre. Très chic.", "Eating on the floor. Very classy." },
		{ "Si tu pouvais te battre aussi bien que tu manges…", "If only you fought as well as you eat…" } },
	VIEW = { { "Une nouvelle zone ! Tu sais lire une carte, au moins ?", "A new zone! You can read a map, right?" },
		{ "Joli ! Pour une fois qu'on ne tourne pas en rond.", "Nice! For once we're not going in circles." },
		{ "Nouvelle zone ! On était censés venir ici, ou on s'est perdus ?", "New zone! Were we meant to come here, or are we lost?" },
		{ "Joli coin. Le cimetière le plus proche est où, déjà ?", "Nice place. Where's the nearest graveyard, again?" },
		{ "Tu as ouvert la carte ? Non ? Ça explique tout.", "Did you open the map? No? That explains everything." },
		{ "Superbe ! Les monstres ici ont l'air de t'attendre.", "Gorgeous! The monsters here seem to be expecting you." },
		{ "On découvre un lieu ! Ou on fait encore un détour de trois heures ?", "Discovering a place! Or another three-hour detour?" },
		{ "Ah, du paysage ! Ça change de tes chutes de falaise.", "Ah, scenery! Makes a change from your cliff dives." },
		{ "Nouvelle région. Même aventurier. On croise les doigts.", "New region. Same adventurer. Fingers crossed." },
		{ "Respire l'air frais. Et regarde ta carte, pour une fois.", "Breathe the fresh air. And check the map, for once." } },
	IDLE = { { "Tu as quelque chose sur le nez. Non, je rigole.", "You've got something on your nose. No, kidding." },
		{ "Je parie que tu ne sais pas où on est. Moi non plus !", "Bet you don't know where we are. Me neither!" },
