		{ "Si tu ne bouges plus, je vends tes gris.", "If you don't move, I'm selling your greys." },
		{ "On fait une statue ? Tu es très doué.", "Playing statues? You're very good at it." },
		{ "Tes sacs débordent de cailloux et de vieilles dents. Tu collectionnes ?", "Your bags overflow with rocks and old teeth. Collecting?" },
		{ "Je compte jusqu'à dix et je pars à l'aventure sans toi.", "I'll count to ten and go adventuring without you." },
		{ "Toujours là ? Ou je parle à une silhouette ?", "Still there? Or am I talking to a cardboard cutout?" },
		{ "Pause interminable n° 3. Je tiens le compte.", "Endless break number 3. I'm keeping count." } },
	EVOLVE = { { "Me voilà %s ! Bientôt plus grand que toi.", "Now I'm %s! Soon taller than you." },
		{ "Me voilà %s ! Et toi, toujours le même. C'est mignon.", "Now I'm %s! And you're still the same. Cute." },
		{ "%s ! Je grandis plus vite que tes compétences.", "%s! I'm growing faster than your skills." },
		{ "Je deviens %s ! Ne prends pas ce ton jaloux.", "I'm becoming %s! Don't sound so jealous." } },
	CAMP = { { "Un feu ! Attention à tes sourcils, cette fois.", "A fire! Mind your eyebrows this time." },
		{ "Un feu ! Tu sais l'allumer, ou je souffle sur les braises ?", "A fire! Can you light it, or shall I blow on the embers?" },
		{ "Assieds-toi, raconte-moi tes exploits. Ça ira vite.", "Sit down, tell me your exploits. Won't take long." },
		{ "Un feu de camp. Ne t'approche pas trop, je te connais.", "A campfire. Not too close, I know you." } },
