		{ "Un objet gris ! Encore un trésor pour ta collection de déchets.", "A grey item! Another gem for your junk collection." },
		{ "Ça vaut bien… trois pièces de cuivre. Bravo.", "That's worth… three copper. Congrats." },
		{ "Tu ramasses même les dents de loup ? Respect.", "You even pick up wolf teeth? Respect." },
		{ "Tu vas le porter ou le garder vingt niveaux ?", "Will you wear it, or keep it for twenty levels?" },
		{ "Ooh ! Ah non, c'est encore un vieux chiffon.", "Ooh! Oh no, another old rag." },
		{ "Encore un truc qui finira chez le marchand. Dans un mois.", "Another thing headed to the vendor. Next month." },
		{ "Butin ! Il y a encore de la place ? Pour combien de temps ?", "Loot! Any room left? For how long?" },
		{ "Superbe trouvaille. Si on aime les cailloux.", "Superb find. If you like rocks." } },
	QUEST = { { "Mission accomplie ! Tu vois, quand tu veux.", "Mission done! See, you can when you want." },
		{ "Mission accomplie ! Tu as quand même mis trois heures.", "Mission done! Only took you three hours." },
		{ "Quête rendue ! Le PNJ avait fini par s'endormir.", "Quest done! The NPC had nodded off." },
		{ "Bravo ! Il fallait juste lire l'objectif, en fait.", "Well done! You just had to read the objective." },
