	ADVICE_ELITE = { { "%s ! Même toi, tu ne devrais pas tenter ça.", "%s! Even you shouldn't try that." },
		{ "%s ! Vas-y, je filme.", "%s! Go on, I'm filming." },
		{ "%s… je te réserve une place au cimetière ?", "%s… shall I book you a spot at the graveyard?" },
		{ "%s. Tu as vu sa tête de mort dorée ? C'est un indice.", "%s. See the golden skull? That's a hint." } },
