	ADVICE_FOOD = { { "Plus que %d vivres ? Tu as tout mangé en cachette ?", "Only %d food? Did you eat it all in secret?" },
		{ "Plus que %d vivres. Tu grignotes en marchant, avoue.", "Only %d food left. You snack while walking, admit it." },
