		{ "Coucou ! Moi c'est %s. Tu m'as manqué, même pendant une minute.", "Hi! I'm %s. I missed you, even for a minute." },
		{ "%s est prêt ! Et tout câlin, comme d'habitude.", "%s is ready! And cuddly, as usual." },
		{ "Salut, c'est %s ! On part main dans la patte ?", "Hi, it's %s! Shall we go paw in hand?" } },
	LEVEL = { { "Niveau %d ! Je suis si fier de toi !", "Level %d! I'm so proud of you!" },
		{ "Niveau %d ! Câlin de félicitations !", "Level %d! Congratulations hug!" },
		{ "Niveau %d ! Tu as grandi… même si tu te perds toujours autant.", "Level %d! You've grown… though you still get lost as much." },
		{ "Niveau %d ! Bisou sur le front. Même s'il est un peu cabossé.", "Level %d! A kiss on the forehead. Even if it's a bit dented." },
		{ "Niveau %d ! Je savais que tu y arriverais. Un jour.", "Level %d! I knew you'd get there. Eventually." },
