		{ "Bravo ! Viens là que je te félicite.", "Well done! Come here so I can congratulate you." },
		{ "Tu as gagné ! Tu n'as pas trop mal ? Montre.", "You won! Not too hurt? Let me see." },
		{ "Bravo ! Même si c'était un tout petit, ça compte.", "Well done! Even if it was a tiny one, it counts." },
		{ "Oh, le pauvre lapin… bon, tu ne l'as pas fait exprès.", "Oh, the poor bunny… well, you didn't mean it." },
		{ "Mon héros ! Un peu essoufflé, mais mon héros.", "My hero! A bit out of breath, but my hero." },
		{ "Tu t'es bien battu. Câlin de récompense ?", "You fought well. Reward hug?" },
		{ "Ouf, c'est fini. Je n'aime pas quand tu te bagarres.", "Phew, it's over. I don't like it when you scrap." } },
	DEAD = { { "Non… je reste près de toi, je ne bouge pas.", "No… I'm staying right by you, not moving." },
		{ "Je t'attends ici. Reviens vite, tu me manques déjà.", "I'll wait here. Come back soon, I miss you already." },
		{ "Oh non… tu t'es fait mal ? Je souffle sur le bobo.", "Oh no… did you get hurt? I'll kiss it better." },
		{ "Je garde ta place au chaud. Ne te perds pas en revenant.", "I'll keep your spot warm. Don't get lost coming back." },
		{ "Tu es tombé… je t'aime quand même. Surtout là.", "You fell… I love you anyway. Especially now." },
		{ "Prends le chemin le plus court, d'accord ? Pas comme d'habitude.", "Take the short way, OK? Not like usual." },
		{ "Je ne pleure pas. C'est la pluie. Il ne pleut pas.", "I'm not crying. It's rain. It isn't raining." },
		{ "Reviens vite, j'ai un câlin en attente pour toi.", "Come back soon, I've got a hug on hold for you." } },
	REZ = { { "Te revoilà ! Je t'ai tellement attendu ! Câlin !", "You're back! I waited so long! Hug!" },
		{ "Te revoilà ! Je ne te lâche plus. Plus jamais.", "You're back! I'm not letting go. Ever." },
		{ "Câlin de retour ! Et on évite ce monstre, cette fois ?", "Welcome-back hug! And we avoid that monster this time?" },
		{ "Tu as pris le chemin des écoliers, mais tu es là !", "You took the scenic route, but you're here!" },
		{ "Ouf ! J'ai gardé ton sac. Et ma patience.", "Phew! I kept your bag. And my patience." },
		{ "Debout, mon cœur. On recommence, doucement.", "Up you get, sweetheart. Let's start again, gently." },
		{ "Tu es revenu pour moi ? Je le savais !", "You came back for me? I knew it!" } },
	EAT = { { "On mange ensemble, c'est encore meilleur.", "Eating together makes it even better." },
		{ "Tu manges ? Une bouchée pour toi, une pour moi.", "Eating? One bite for you, one for me." },
		{ "Mange doucement, tu vas avoir le hoquet.", "Eat slowly, you'll get hiccups." },
		{ "Tu as de la sauce sur le menton. C'est mignon.", "You've got sauce on your chin. It's cute." },
		{ "Un repas ensemble, c'est le meilleur moment.", "A meal together is the best moment." },
		{ "Tu grignotes encore ? Bon, je ne dis rien. Je partage.", "Snacking again? Fine, I won't say a thing. I'll share." },
		{ "Je te tiens compagnie. Et je surveille les miettes.", "I'll keep you company. And watch the crumbs." } },
	VIEW = { { "C'est beau… et encore plus beau avec toi.", "It's beautiful… even more with you." },
		{ "Un nouvel endroit ! Tiens-moi fort, on ne sait jamais.", "A new place! Hold me tight, just in case." },
		{ "C'est joli ici. On fait une photo, tous les deux ?", "It's pretty here. A photo of the two of us?" },
		{ "On découvre ça ensemble ! Ne te perds pas, hein.", "We discover it together! Don't get lost, OK?" },
		{ "Je ne connais personne ici… sauf toi. Ça suffit.", "I don't know anyone here… except you. That's enough." },
		{ "Oh, ce paysage ! Presque aussi beau que ton sourire.", "Oh, this view! Almost as lovely as your smile." },
		{ "Encore un détour ? Je ne dis rien, j'aime bien te suivre.", "Another detour? I won't complain, I like following you." } },
	IDLE = { { "Je suis bien, là, avec toi.", "I'm happy here, with you." },
		{ "Tu sais que tu es mon aventurier préféré ?", "You know you're my favourite adventurer?" },
		{ "Tu es encore là ? Je te fais un câlin en attendant.", "Still there? I'll hug you while I wait." },
		{ "Tu t'es endormi ? Je veille sur toi.", "Did you fall asleep? I'll watch over you." },
		{ "On reste comme ça ? Moi, ça me va très bien.", "Shall we stay like this? Suits me fine." },
		{ "Tu sais que tu ronfles un peu quand tu ne bouges plus ?", "You know you snore a bit when you stop moving?" },
		{ "Je te tricote une écharpe. En pensée.", "I'm knitting you a scarf. In my head." },
		{ "Tes sacs sont pleins de vieux trucs… comme mon cœur de souvenirs.", "Your bags are full of old stuff… like my heart, of memories." } },
	EVOLVE = { { "Me voilà %s ! Grâce à toi. Merci, merci !", "Now I'm %s! Thanks to you. Thank you, thank you!" },
		{ "Me voilà %s ! Tu m'aimes toujours autant ?", "Now I'm %s! Do you still love me as much?" },
		{ "Je deviens %s ! Toujours aussi câlin, promis.", "I'm becoming %s! Still just as cuddly, promise." },
		{ "%s ! Plus grand, mais je tiens encore sur tes genoux.", "%s! Bigger, but I still fit on your lap." } },
	CAMP = { { "Un feu… on se serre l'un contre l'autre ?", "A fire… shall we snuggle up?" },
		{ "Un feu ! Je me blottis contre toi, d'accord ?", "A fire! I'll snuggle up to you, OK?" },
		{ "On se réchauffe les pattes, et les cœurs.", "Let's warm our paws, and our hearts." },
		{ "Le feu, toi, moi. Rien d'autre.", "The fire, you, me. Nothing else." } },
	LOOT = { { "Un cadeau ! C'est pour moi ? Non ? Pas grave.", "A present! Is it for me? No? That's fine." },
		{ "Oh ! C'est joli ! Tu me le prêtes ?", "Oh! It's pretty! Will you lend it to me?" },
		{ "Encore un objet gris… tu gardes tout, comme moi avec toi.", "Another grey item… you keep everything, like I keep you." },
		{ "Un trésor ! Tu es le plus doué pour trouver des choses.", "A treasure! You're the best at finding things." },
		{ "C'est pour moi ? Dis oui. Même si c'est non.", "Is it for me? Say yes. Even if it's no." },
		{ "Mets-le dans le sac. S'il reste de la place…", "Put it in the bag. If there's room left…" },
		{ "Tu as l'œil ! Et moi, j'ai toi.", "You've got an eye for it! And I've got you." } },
	QUEST = { { "Mission accomplie ! Tu es formidable.", "Mission done! You're wonderful." },
		{ "Mission accomplie ! Je suis si fier que je pourrais pleurer.", "Mission complete! I'm so proud I could cry." },
		{ "Bravo ! Même si on a tourné en rond un moment.", "Well done! Even if we went in circles for a while." },
		{ "Quête rendue ! Un câlin pour la peine.", "Quest done! A hug for your trouble." },
		{ "Tu as aidé quelqu'un. Tu es le meilleur.", "You helped someone. You're the best." },
		{ "Encore une ! Tu en fais beaucoup pour les autres, tu sais.", "Another one! You do so much for others, you know." },
		{ "C'était long, mais c'est fini. Viens là.", "It took a while, but it's done. Come here." } },
	ADVICE_ELITE = { { "%s… j'ai peur. Reste près de moi, on passe ailleurs ?", "%s… I'm scared. Stay close, go another way?" },
		{ "%s… je ne veux pas te perdre. On fait le tour ?", "%s… I don't want to lose you. Go around?" },
		{ "Pas %s, s'il te plaît. Pas aujourd'hui.", "Not %s, please. Not today." },
		{ "%s a l'air méchant. Toi, tu es gentil. On s'en va.", "%s looks mean. You're nice. Let's go." } },
	ADVICE_HEALTH = { { "Tu as mal ? Viens, on se repose, je veille sur toi.", "Are you hurt? Come, let's rest, I'll watch over you." },
		{ "Tu es tout égratigné… laisse-moi te soigner. Avec un câlin.", "You're all scratched up… let me heal you. With a hug." },
		{ "Assieds-toi près de moi. On souffle un peu.", "Sit by me. Let's catch our breath." },
		{ "Tu as une sale mine, mon cœur. Repos, d'accord ?", "You look rough, sweetheart. Rest, OK?" } },
	ADVICE_FOOD = { { "Plus que %d vivres… je ne veux pas que tu aies faim.", "Only %d food… I don't want you to go hungry." },
		{ "Plus que %d vivres… je te donne ma part, si tu veux.", "Only %d food left… you can have my share." },
		{ "%d vivres. On en rachète, pour qu'on n'ait jamais faim ?", "%d food. Let's buy more, so we never go hungry?" },
		{ "Plus que %d vivres. Tu as encore tout grignoté, hein ?", "Only %d food. You nibbled it all again, didn't you?" } },
	ADVICE_BAGS = { { "%d places… garde-m'en une, je me ferai tout petit.", "%d slots… save me one, I'll make myself tiny." },
		{ "Plus que %d places… tu gardes trop de souvenirs, toi aussi.", "Only %d slots… you hang on to too many keepsakes, too." },
		{ "%d places. Et si on vendait un peu de cailloux ?", "%d slots. How about we sell a few rocks?" },
		{ "Plus que %d places. Moi, je peux voyager sur ton épaule.", "Only %d slots. I can ride on your shoulder." } },
	NOTICE = { { "Tu ne m'as pas caressé depuis longtemps… je dis ça comme ça.", "You haven't petted me in a while… just saying." },
		{ "Un petit câlin ? Juste un ? Clique sur moi !", "A little cuddle? Just one? Click me!" },
		{ "Tu m'as oublié ? Je suis là, en bas. Tout petit.", "Did you forget me? I'm down here. Tiny." },
		{ "Ça fait vingt minutes sans caresse. Je compte, tu sais.", "Twenty minutes without a pet. I'm counting, you know." },
		{ "Tu ramasses tous les cailloux du monde, mais pas moi ?", "You pick up every rock in the world, but not me?" },
		{ "Un clic, rien qu'un. Ça ne coûte rien.", "One click, just one. It's free." },
		{ "Je boude. Un tout petit peu. Un câlin et c'est oublié.", "I'm sulking. A tiny bit. One cuddle and it's forgotten." },
		{ "Tu as le temps de taper des sangliers, mais pas de me caresser ?", "Time to whack boars, but not to pet me?" } },
}

-- Caractères propres à une apparence
