		{ "Un combat évité est souvent un combat gagné. Celui-là, non.", "A fight avoided is often a fight won. Not this one." },
		{ "Hou. Tu as frappé fort. Vise juste, la prochaine fois.", "Hoo. You struck hard. Strike true next time." },
		{ "L'adversaire était faible. Ne le dis à personne.", "The foe was weak. Tell no one." } },
	DEAD = { { "Tomber n'est rien. Se relever est tout.", "Falling is nothing. Rising is everything." },
		{ "Le sol enseigne l'humilité. Tu prends beaucoup de leçons.", "The ground teaches humility. You take many lessons." },
		{ "Celui qui fonce tête baissée finit par voir le sol de près.", "Who charges head down ends up seeing the ground up close." },
		{ "Le chemin du cimetière, tu le connais mieux que moi.", "You know the graveyard road better than I." },
		{ "Hou. L'échec est un maître. Tu es son élève assidu.", "Hoo. Failure is a teacher. You are its keenest pupil." },
		{ "La sagesse vient de l'expérience. Tu en accumules beaucoup.", "Wisdom comes from experience. You gather plenty." },
		{ "Le ruisseau contourne la pierre. Toi, tu fonces dedans.", "The stream flows around the stone. You run into it." } },
	REZ = { { "Te voilà relevé. Plus sage qu'avant, j'espère.", "Back on your feet. Wiser than before, I hope." },
		{ "Tu reviens. Mais as-tu compris pourquoi tu es parti ?", "You return. But do you understand why you left?" },
		{ "Le phénix renaît. Toi, tu reviens à pied. C'est déjà ça.", "The phoenix is reborn. You walk back. Still something." },
		{ "Hou. Te voilà. Le même, ou un peu plus sage ?", "Hoo. Here you are. The same, or a little wiser?" },
