		{ "Le corps revient vite. La fierté, plus lentement.", "The body returns quickly. Pride, more slowly." },
		{ "Retourne au combat, mais avec ta tête, cette fois.", "Return to the fight, but with your head this time." } },
	EAT = { { "Un ventre plein garde l'esprit clair.", "A full belly keeps the mind clear." },
		{ "Qui mange vite digère mal. Hou.", "Who eats fast digests poorly. Hoo." },
		{ "Le sage mange avant d'avoir faim. Toi, après.", "The wise eat before hunger. You, after." },
		{ "Un repas est une pause. Une sieste en est une autre.", "A meal is a pause. A nap is another." },
