		{ "Un feu. Assieds-toi, et réfléchis à tes choix de la journée.", "A fire. Sit, and reflect on today's choices." },
		{ "Le feu ne se presse pas. Prends exemple.", "Fire does not hurry. Follow its lead." },
		{ "Autour du feu, même les maladroits deviennent conteurs.", "Around the fire, even the clumsy become storytellers." } },
	LOOT = { { "Un trésor. Mais le vrai trésor, c'est le voyage.", "A treasure. But the real treasure is the journey." },
		{ "Qui ramasse tout porte tout. Hou.", "Who gathers everything carries everything. Hoo." },
		{ "L'objet gris a sa valeur. Elle est faible, mais elle existe.", "The grey item has worth. Small, but real." },
		{ "La richesse ne se mesure pas en cailloux. Pas les tiens, en tout cas.", "Wealth is not measured in rocks. Not yours, at least." },
		{ "Un bel objet. Garde-le, ou laisse-le. Mais décide.", "A fine item. Keep it or leave it. But decide." },
		{ "Le trésor qu'on cherche n'est pas toujours celui qu'on trouve.", "The treasure sought isn't always the treasure found." },
		{ "Hou. Le sage voyage léger. Tu n'es pas encore sage.", "Hoo. The wise travel light. You are not wise yet." } },
