		{ "Bien. Une graine plantée, un arbre demain.", "Good. A seed planted, a tree tomorrow." },
		{ "La parole tenue honore le voyageur. Même égaré.", "A word kept honours the traveller. Even a lost one." } },
	ADVICE_ELITE = { { "%s. Le courage sans prudence n'est que folie.", "%s. Courage without caution is mere folly." },
		{ "%s. Le brave sait aussi quand reculer.", "%s. The brave also know when to retreat." },
		{ "Hou. %s est un mur. On ne traverse pas les murs.", "Hoo. %s is a wall. One does not walk through walls." },
		{ "%s. Le cimetière est plein de gens qui n'ont pas écouté.", "%s. The graveyard is full of those who didn't listen." } },
	ADVICE_HEALTH = { { "Le sage se repose avant d'être las. Il est temps.", "The wise rest before they are weary. It is time." },
		{ "La lame la plus fine casse si on la force. Repose-toi.", "The finest blade breaks if forced. Rest." },
