		{ "Présage funeste confirmé. Je déteste avoir raison.", "Dire omen confirmed. I hate being right." },
		{ "Le gardien du cimetière m'a dit : « Encore lui ? »", "The graveyard keeper told me: «Him again?»" } },
	REZ = { { "Tu as traversé le voile et tu en es revenu. Rare présage.", "You crossed the veil and came back. A rare omen." },
